import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import {
    TODAY_RAIL_DEFAULT_LAYOUT,
    TODAY_RAIL_FOOT_PANE,
    TODAY_RAIL_LOCKED_PANE,
    TodayRailLayout,
    arrangeablePanes,
    movePane,
    toggleHiddenPane,
} from './todayRailLayout'
import { TodayRailPane, todayShellLogic } from './todayShellLogic'
import { TODAY_USER_PERSIST_OPTIONS } from './todayUserPersistOptions'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayRailLayoutLogicValues {
    railPanes: TodayRailPane[] // todayShellLogic
    arrangedPanes: TodayRailPane[]
    customizeOpen: boolean
    footPaneShown: boolean
    hiddenRailPanes: TodayRailPane[]
    layoutCustomized: boolean
    moreMenuOpen: boolean
    railHidden: TodayRailPane[]
    railLayout: TodayRailLayout | null
    shownRailPanes: TodayRailPane[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayRailLayoutLogicActions {
    moveRailPane: (
        pane: TodayRailPane,
        toIndex: number
    ) => {
        pane: TodayRailPane
        toIndex: number
    }
    resetRailLayout: () => {
        value: true
    }
    setCustomizeOpen: (open: boolean) => {
        open: boolean
    }
    setMoreMenuOpen: (open: boolean) => {
        open: boolean
    }
    setRailOrder: (order: TodayRailPane[]) => {
        order: TodayRailPane[]
    }
    toggleRailPane: (pane: TodayRailPane) => {
        pane: TodayRailPane
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayRailLayoutLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        railHidden: (railLayout: TodayRailLayout | null) => TodayRailPane[]
        arrangedPanes: (railLayout: TodayRailLayout | null, railPanes: TodayRailPane[]) => TodayRailPane[]
        shownRailPanes: (
            arrangedPanes: TodayRailPane[],
            railHidden: TodayRailPane[],
            railPanes: TodayRailPane[]
        ) => TodayRailPane[]
        hiddenRailPanes: (arrangedPanes: TodayRailPane[], railHidden: TodayRailPane[]) => TodayRailPane[]
        footPaneShown: (railPanes: TodayRailPane[]) => boolean
        layoutCustomized: (railLayout: TodayRailLayout | null) => boolean
    }
}

export type todayRailLayoutLogicType = MakeLogicType<
    todayRailLayoutLogicValues,
    todayRailLayoutLogicActions,
    Record<string, any>,
    todayRailLayoutLogicMeta
>

export const todayRailLayoutLogic = kea<todayRailLayoutLogicType>([
    path(['layout', 'today', 'todayRailLayoutLogic']),
    connect(() => ({
        values: [todayShellLogic, ['railPanes']],
    })),
    actions({
        moveRailPane: (pane: TodayRailPane, toIndex: number) => ({ pane, toIndex }),
        setRailOrder: (order: TodayRailPane[]) => ({ order }),
        toggleRailPane: (pane: TodayRailPane) => ({ pane }),
        resetRailLayout: true,
        setCustomizeOpen: (open: boolean) => ({ open }),
        setMoreMenuOpen: (open: boolean) => ({ open }),
    }),
    reducers({
        // Null until the person arranges the rail, so the defaults apply and a reset is one write.
        railLayout: [
            null as TodayRailLayout | null,
            TODAY_USER_PERSIST_OPTIONS,
            {
                setRailOrder: (state, { order }) => ({ ...(state ?? TODAY_RAIL_DEFAULT_LAYOUT), order }),
                toggleRailPane: (state, { pane }) => toggleHiddenPane(state ?? TODAY_RAIL_DEFAULT_LAYOUT, pane),
                resetRailLayout: () => null,
            },
        ],
        customizeOpen: [
            false,
            {
                setCustomizeOpen: (_, { open }) => open,
            },
        ],
        // Lives here rather than in the menu, so the design changelog's demo can open it.
        moreMenuOpen: [
            false,
            {
                setMoreMenuOpen: (_, { open }) => open,
            },
        ],
    }),
    selectors({
        railHidden: [
            (s) => [s.railLayout],
            (railLayout: TodayRailLayout | null): TodayRailPane[] => (railLayout ?? TODAY_RAIL_DEFAULT_LAYOUT).hidden,
        ],
        arrangedPanes: [
            (s) => [s.railLayout, s.railPanes],
            (railLayout: TodayRailLayout | null, railPanes: TodayRailPane[]): TodayRailPane[] =>
                arrangeablePanes(railLayout?.order ?? null, railPanes),
        ],
        /** The panes the rail lists, in order. Products is pinned below them, outside this list. */
        shownRailPanes: [
            (s) => [s.arrangedPanes, s.railHidden, s.railPanes],
            (arrangedPanes: TodayRailPane[], railHidden: TodayRailPane[], railPanes: TodayRailPane[]) => [
                ...(railPanes.includes(TODAY_RAIL_LOCKED_PANE) ? [TODAY_RAIL_LOCKED_PANE] : []),
                ...arrangedPanes.filter((pane) => !railHidden.includes(pane)),
            ],
        ],
        hiddenRailPanes: [
            (s) => [s.arrangedPanes, s.railHidden],
            (arrangedPanes: TodayRailPane[], railHidden: TodayRailPane[]) =>
                arrangedPanes.filter((pane) => railHidden.includes(pane)),
        ],
        footPaneShown: [(s) => [s.railPanes], (railPanes: TodayRailPane[]) => railPanes.includes(TODAY_RAIL_FOOT_PANE)],
        layoutCustomized: [(s) => [s.railLayout], (railLayout: TodayRailLayout | null) => railLayout !== null],
    }),
    listeners(({ actions, values }) => ({
        moveRailPane: ({ pane, toIndex }) => {
            actions.setRailOrder(movePane(values.arrangedPanes, pane, toIndex))
            // pinned: analytics event name and properties. Renaming them breaks dashboards.
            posthog.capture('today rail customized', { pane, moved_to: toIndex })
        },
        // Runs after the reducer, so `railHidden` already holds the new state.
        toggleRailPane: ({ pane }) => {
            posthog.capture('today rail customized', { pane, shown: !values.railHidden.includes(pane) })
        },
        resetRailLayout: () => {
            posthog.capture('today rail customized', { reset: true })
        },
    })),
])
